// fieldMaps holds the three column→field-index lookup maps for a struct type.
// Built once per reflect.Type and cached in fieldMapCache so the reflect.Field
// walk, json-tag extraction, and snake_case conversion don't repeat per row.
type fieldMaps struct {
	tagMap   map[string]int
	nameMap  map[string]int
	snakeMap map[string]int
}

// fieldMapCache caches fieldMaps by reflect.Type. The mapping for a given struct
// type never changes, so this is safe as a process-global sync.Map.
var fieldMapCache = sync.Map{}

// loadFieldMaps returns the cached fieldMaps for elemType, building and storing
// them on first use. This is the Pass 1 optimization: column→field resolution is
// done once per type, not once per row.
func loadFieldMaps(elemType reflect.Type) *fieldMaps {
	if cached, ok := fieldMapCache.Load(elemType); ok {
		if m, _isOk := cached.(*fieldMaps); _isOk {
			return m
		}
	}
	maps := buildFieldMaps(elemType)
	fieldMapCache.Store(elemType, maps)
	return maps
}

// buildFieldMaps constructs the tag/name/snake lookup maps for a struct type.
// Mapping priority: json tag > exact name (case-insensitive) > snake_case.
func buildFieldMaps(elemType reflect.Type) *fieldMaps {
	numFields := elemType.NumField()
	tagMap := make(map[string]int, numFields)
	nameMap := make(map[string]int, numFields)
	snakeMap := make(map[string]int, numFields)
	for i := range numFields {
		field := elemType.Field(i)
		if !field.IsExported() {
			continue
		}
		tag := field.Tag.Get("json")
		if tag != "" && tag != "-" {
			parts := strpkg.Split(tag, ",")
			tagMap[parts[0]] = i
		}
		nameMap[strpkg.ToLower(field.Name)] = i
		snakeMap[camelToSnake(field.Name)] = i
	}
	return &fieldMaps{tagMap: tagMap, nameMap: nameMap, snakeMap: snakeMap}
}

// resolveColumns maps each column name to a struct field index (-1 = unmapped).
// Uses the cached fieldMaps so this is pure map lookups, no reflection.
func resolveColumns(maps *fieldMaps, columns []string) []int {
	indices := make([]int, len(columns))
	for ci, col := range columns {
		lowerCol := strpkg.ToLower(col)
		if idx, ok := maps.tagMap[col]; ok {
			indices[ci] = idx
		} else if idx, ok := maps.nameMap[lowerCol]; ok {
			indices[ci] = idx
		} else if idx, ok := maps.snakeMap[lowerCol]; ok {
			indices[ci] = idx
		} else {
			indices[ci] = -1
		}
	}
	return indices
}

