// nullSafeField wraps a struct field for NULL-safe scanning.
// SQL NULL values become the Go zero value of the target field type.
type nullSafeField struct {
	target reflect.Value
}

func (s *nullSafeField) Scan(value any) error {
	if value == nil {
		return nil
	}
	if s.target.Kind() == reflect.Bool {
		if v, _isOk := value.(int64); _isOk {
			s.target.SetBool(v != 0)
			return nil
		}
		if v, _isOk := value.(int); _isOk {
			s.target.SetBool(v != 0)
			return nil
		}
	}
	if s.target.Kind() == reflect.String {
		s.target.SetString(cast.ToString(value))
		return nil
	}
	src := reflect.ValueOf(value)
	if src.Type().ConvertibleTo(s.target.Type()) {
		s.target.Set(src.Convert(s.target.Type()))
	} else {
		if s.target.Kind() == reflect.String {
			s.target.SetString(fmt.Sprintf("%v", value))
		} else {
			return fmt.Errorf("db: cannot convert %v to %v", src.Type(), s.target.Type())
		}
	}
	return nil
}

// orderedFieldScanners creates null-safe scanners for all exported struct fields
// in declaration order. Used by ScanRow where column names aren't available from sql.Row.
func orderedFieldScanners(elem reflect.Value, elemType reflect.Type) []any {
	numFields := elemType.NumField()
	scanners := make([]any, 0, numFields)
	for i := range numFields {
		field := elemType.Field(i)
		if field.IsExported() {
			scanners = append(scanners, &nullSafeField{target: elem.Field(i)})
		}
	}
	return scanners
}

// camelToSnake converts CamelCase to snake_case.
func camelToSnake(s string) string {
	result := ""
	for i, r := range s {
		if unicode.IsUpper(r) {
			if i > 0 {
				result = result + "_"
			}
			result = strpkg.ToLower(result + string(r))
		} else {
			result = result + string(r)
		}
	}
	return result
}

// QuoteIdentifier wraps a SQL identifier in double quotes and escapes any
// embedded double quotes. Use it for identifiers (table/column names) that
// cannot be parameterized — never for values, which must go through placeholders.
// Example: db.Query(pool, "SELECT * FROM {db.QuoteIdentifier(table)}")
func QuoteIdentifier(name string) string {
	return "\"" + strpkg.ReplaceAll(name, "\"", "\"\"") + "\""
}

// Like escapes LIKE wildcards (\\ % _) in pattern and wraps it in %...% for a
// contains match. Bind the result as a parameter alongside an ESCAPE clause:
//
//	db.Query(pool, "SELECT * FROM users WHERE name LIKE ? ESCAPE '\\'", db.Like(search))
//
// Example: db.Like("50%_off") → "%50\\%\\_off%"
func Like(pattern string) string {
	escaped := strpkg.ReplaceAll(pattern, "\\", "\\\\")
	escaped = strpkg.ReplaceAll(escaped, "%", "\\%")
	escaped = strpkg.ReplaceAll(escaped, "_", "\\_")
	return "%" + escaped + "%"
}

// In returns a parenthesized list of n '?' placeholders for an IN clause
// ('?'-style drivers: SQLite, MySQL). Pass the matching values as arguments.
// Example: db.Query(pool, "SELECT * FROM users WHERE id IN " + db.In(len(ids)), many ids)
func In(n int) string {
	if n <= 0 {
		return "()"
	}
	placeholders := make([]string, n)
	for i := range n {
		placeholders[i] = "?"
	}
	return "(" + strpkg.Join(placeholders, ", ") + ")"
}
